std::array<uint8_t, 64> musig2_partial_sig_agg(
    const std::vector<Scalar>& partial_sigs,
    const MuSig2Session& session) {

    // s = sum(s_i) — CT: use ct::scalar_add instead of fast::operator+=
    // fast::Scalar::operator+= has a data-dependent ge(ORDER) branch in its
    // final modular reduction. Partial sigs contain signer-secret contributions;
    // use branchless ct::scalar_add throughout the accumulation (CT-002 fix).
    Scalar s = Scalar::zero();
    for (const auto& si : partial_sigs) {
        s = secp256k1::ct::scalar_add(s, si);
    }

    // BIP-327: add the additive-tweak correction e*g*tacc so the aggregated signature
    // verifies against the tweaked aggregate key. tweak_s = 0 when no tweaks were applied.
    s = secp256k1::ct::scalar_add(s, session.tweak_s);

    // Fail-closed: degenerate aggregated signature is a security failure
    if (s.is_zero_ct() || session.R.is_infinity()) {
        return {};  // all-zero array signals failure to caller
    }

    // Final signature: (R.x, s)
    auto R_x = session.R.x().to_bytes();
    auto s_bytes = s.to_bytes();
    secure_erase(&s, sizeof(s));

    std::array<uint8_t, 64> sig{};
    std::memcpy(sig.data(), R_x.data(), 32);
    std::memcpy(sig.data() + 32, s_bytes.data(), 32);
    return sig;
}

SchnorrSignature
frost_aggregate(const std::vector<FrostPartialSig>& partial_sigs,
                const std::vector<FrostNonceCommitment>& nonce_commitments,
                const Point& group_public_key,
                const std::array<std::uint8_t, 32>& msg) {
    if (!valid_unique_nonce_commitment_ids(nonce_commitments)) {
        return SchnorrSignature{{}, Scalar::zero()};
    }

    // Group commitment R (compute binding factors inline to avoid heap scratch).
    Point R = compute_group_commitment_inline_binding(
        group_public_key,
        nonce_commitments,
        msg,
        0,
        nullptr);

    // BIP-340: ensure even y
    // NOTE: R is a public group commitment; VT field inverse is safe here.
    auto R_y = R.y().to_bytes();
    if (R_y[31] & 1) {
        R.negate_inplace();
    }

    // Aggregate: s = Sum z_i
    Scalar s = Scalar::zero();
    for (const auto& ps : partial_sigs) {
        s = ct::scalar_add(s, ps.z_i);
    }

    // Fail-closed: degenerate aggregated signature is a protocol failure.
    // BIP-340 Rule 14: reject if R.x is all-zeros (infinity or degenerate R).
    SchnorrSignature sig;
    sig.r = R.x().to_bytes();
    {
        std::uint8_t acc = 0;
        for (auto b : sig.r) acc |= b;
        if (acc == 0 || s.is_zero_ct() || R.is_infinity()) {
            return SchnorrSignature{{}, Scalar::zero()};
        }
    }
    sig.s = s;
    return sig;
}

Scalar pedersen_blind_sum(const Scalar* blinds_in,
                          std::size_t n_in,
                          const Scalar* blinds_out,
                          std::size_t n_out) {
    Scalar sum = Scalar::zero();
    for (std::size_t i = 0; i < n_in; ++i) {
        sum = sum + blinds_in[i];
    }
    for (std::size_t i = 0; i < n_out; ++i) {
        sum = sum - blinds_out[i];
    }
    return sum;
}
